"""Write this service's OpenAPI document, generated by FastAPI from the code, to openapi.json.

Run from the service folder: python export_openapi.py
CI runs it too and fails if the committed openapi.json differs from the code.
"""
import json
from pathlib import Path

from app import app

path = Path(__file__).parent / "openapi.json"
path.write_text(json.dumps(app.openapi(), indent=2, sort_keys=True) + "\n", encoding="utf-8")
print(f"wrote {path.name}")
